window.MG_LAZY_DATA["data/lazy/courses/b149-8ea2c5869a891423.json"]={sha256:"8ea2c5869a891423b7bc11f8c7b21376cbc5be5f71a97dc9d9af69d76303c172",value:{"id":"b149","title":"隧道台階法施工","titleEn":"Bench excavation for tunnels","category":"underground","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"台階法把上半斷面、下半斷面與仰拱分階段形成，各階段的支承位置和自由邊界都會改變。本課追蹤拱腳承載、保留核心、左右開挖與閉合距離的互相影響，再以幾何、物料、收斂及排水資料進行核對。所有算例服務於辨識荷載轉移與資料限制，不指定實際台階長度、開挖步距或拆除程序。","summaryEn":"Bench excavation forms the upper section, lower section and invert in stages, changing support locations and free boundaries along the way. The course follows arch-foot bearing, retained core, left-right excavation and closure distance, checking their interaction through geometry, quantities, convergence and drainage evidence. Calculations identify load transfer and data limitations; they do not prescribe actual bench lengths, excavation increments or removal procedures.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、開挖、注漿或受限空間作業許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, excavation, grouting or confined-space permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"ug-excavation","subcategoryTitle":"分部開挖與施工序列","subcategoryTitleEn":"Sequential excavation and construction stages","learningTrack":"underground","learningSubdiscipline":"ug-excavation","learningTags":["underground","ug-excavation","excavation"],"architectureFamily":"excavation","architectureNodes":[["上半斷面與反力位置","Upper section and reaction locations"],["拱腳面積與接觸承壓","Arch-foot area and contact bearing"],["左右下挖與差異沉陷","Asymmetric lower excavation and settlement"],["閉合追趕與相對速度","Closure catch-up and relative speed"],["閉合後淨空與驗收餘量","Post-closure clearance and acceptance allowance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[3,1]],"diagram":{"type":"excavation","labels":["上半斷面與反力位置","拱腳面積與接觸承壓","左右下挖與差異沉陷","閉合追趕與相對速度","閉合後淨空與驗收餘量"],"labelsEn":["Upper section and reaction locations","Arch-foot area and contact bearing","Asymmetric lower excavation and settlement","Closure catch-up and relative speed","Post-closure clearance and acceptance allowance"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"以下原創算例針對台階開挖的拱腳承載、核心保留與仰拱閉合時序，每個輸入都是教學假設而非地標實測資料。教學假設，非現場設定或設計允收值。假設垂直合力W=900 kN且對稱，左右反力各450 kN；若假設分配為60%與40%，則為540及360 kN，總和仍為900 kN。教學假設，非現場設定或設計允收值。假設兩作業點穩定相距12 m、同步平均推進2 m/day，一斷面等待時間12/2=6 days；加入3天停頓則為9 days，非允許等待期。兩式只回答各自所列的量與邊界，不應把單一平均結果當成整體穩定證明。請另以最不利的幾何、時間或接觸條件代入，分別標示量測誤差和模型偏差；交接記錄須保留原單位、資料日期以及未能確認的條件。","textEn":"This original worked example examines bench excavation, arch-foot bearing, retained core and invert-closure timing. Every input is a teaching assumption, not a measured value from a landmark. Teaching assumptions, not operating settings or design acceptance limits. Assume vertical resultant W=900 kN. Symmetry gives 450 kN at each side. A hypothetical 60/40 split instead gives 540 and 360 kN, still summing to 900 kN. Teaching assumptions, not operating settings or design acceptance limits. Assume two work points remain 12 m apart while advancing at 2 m/day. A section waits 12/2=6 days; a three-day shutdown makes nine days. Neither is an allowable waiting period. Each relation answers only its stated quantity under its stated boundary conditions. A favorable mean value is not proof of overall stability. Recalculate with an adverse geometry, timing or contact condition, distinguishing measurement uncertainty from model error. The handover record must retain original units, observation dates and conditions that remain unverified; the responsible designer decides whether additional evidence is needed.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":14,"enrichmentVersion":14,"stages":[{"id":"b149-v14-s1","title":"地層條件、邊界與工程系統","titleEn":"Ground conditions, boundaries and engineering system","description":"本階段聚焦「上半斷面與反力位置」與「台階長度與暴露歷程」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Upper section and reaction locations\" and \"Bench length and exposure history\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b149-v14-01","title":"上半斷面與反力位置：機制與系統路徑","titleEn":"Upper section and reaction locations: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":[],"objective":"說明「上半斷面與反力位置」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Upper section and reaction locations” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"上半支護形成後，拱部需求先傳到當時可用的拱腳與地層；下半部未開挖並不表示它沒有受力。簡化對稱反力只適合展示力平衡，傾斜地層和幾何不對稱都會改變左右分配。 假設垂直合力W=900 kN且對稱，左右反力各450 kN；若假設分配為60%與40%，則為540及360 kN，總和仍為900 kN。 一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「上半斷面與反力位置」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"After upper support forms, crown demand reaches the available arch feet and surrounding ground. An unexcavated lower section is still mechanically involved. Symmetric reactions illustrate equilibrium only; inclined strata and asymmetric geometry can alter left-right load sharing. Assume vertical resultant W=900 kN. Symmetry gives 450 kN at each side. A hypothetical 60/40 split instead gives 540 and 360 kN, still summing to 900 kN. A softer arch foot may rotate the lining or redistribute reactions. Average movement can remain modest while local bending increases. Checking total load alone therefore misses demands caused by unequal support conditions. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Upper section and reaction locations” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「總荷載不變就表示左右拱腳需求一定不變。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"An unchanged total load means that demand at each arch foot must also remain unchanged.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「上半斷面與反力位置」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Upper section and reaction locations”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-01-k1","title":"上半斷面與反力位置","titleEn":"Upper section and reaction locations","text":"上半支護形成後，拱部需求先傳到當時可用的拱腳與地層；下半部未開挖並不表示它沒有受力。簡化對稱反力只適合展示力平衡，傾斜地層和幾何不對稱都會改變左右分配。","textEn":"After upper support forms, crown demand reaches the available arch feet and surrounding ground. An unexcavated lower section is still mechanically involved.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：總荷載不變就表示左右拱腳需求一定不變。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: An unchanged total load means that demand at each arch foot must also remain unchanged. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「上半斷面與反力位置」，下列哪一項敘述正確？","questionEn":"Which statement about \"Upper section and reaction locations\" is correct?","options":["總荷載不變就表示左右拱腳需求一定不變。","上半支護形成後，拱部需求先傳到當時可用的拱腳與地層；下半部未開挖並不表示它沒有受力。","台階長度維持固定就代表每個斷面的受力歷程相同。"],"optionsEn":["An unchanged total load means that demand at each arch foot must also remain unchanged.","After upper support forms, crown demand reaches the available arch feet and surrounding ground.","A fixed bench length means that every section experiences an identical loading history."],"answer":1,"explanation":"上半支護形成後，拱部需求先傳到當時可用的拱腳與地層；下半部未開挖並不表示它沒有受力。 其餘選項是常見誤解。","explanationEn":"After upper support forms, crown demand reaches the available arch feet and surrounding ground. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b149-v14-02","title":"上半斷面與反力位置：定量估算","titleEn":"Upper section and reaction locations: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-01"],"objective":"以數值模型估算「上半斷面與反力位置」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Upper section and reaction locations” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設垂直合力W=900 kN且對稱，左右反力各450 kN；若假設分配為60%與40%，則為540及360 kN，總和仍為900 kN。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume vertical resultant W=900 kN. Symmetry gives 450 kN at each side. A hypothetical 60/40 split instead gives 540 and 360 kN, still summing to 900 kN. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將拱腳位置、支護形狀與量測變形對到同一斷面，核對左右地層是否支持對稱假設；比較拱腳沉陷與上部收斂的關聯，若反應不對稱，保留偏載情境送設計者審查而非直接取平均。","observationEn":"How to cross-check: Map arch-foot locations, support shape and measured movement onto one section.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設垂直合力W=900 kN且對稱，左右反力各450 kN；若假設分配為60%與40%，則為540及360 kN，總和仍為900 kN。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume vertical resultant W=900 kN. Symmetry gives 450 kN at each side. A hypothetical 60/40 split instead gives 540 and 360 kN, still summing to 900 kN.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「上半斷面與反力位置」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Upper section and reaction locations\", which statement holds?","options":["核心保留體積比例就是它提供的抗力比例。","出碴重量和幾何量不符時，只要修改密度就能解決。","教學假設，非現場設定或設計允收值。"],"optionsEn":["The retained core volume percentage equals the percentage of resistance it provides.","Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b149-v14-03","title":"上半斷面與反力位置：試驗與驗證","titleEn":"Upper section and reaction locations: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「上半斷面與反力位置」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Upper section and reaction locations” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將拱腳位置、支護形狀與量測變形對到同一斷面，核對左右地層是否支持對稱假設；比較拱腳沉陷與上部收斂的關聯，若反應不對稱，保留偏載情境送設計者審查而非直接取平均。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map arch-foot locations, support shape and measured movement onto one section. Check whether the ground supports symmetry. Compare foot settlement with upper convergence; if behavior is asymmetric, retain eccentric-load scenarios for designer review rather than replacing them with a mean. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：每階段圖面標出當時有效支承而非最終支承，偏載假設與量測差異另列；下半開挖前由設計和現場技術負責人確認荷載路徑。","observationEn":"Site practice: Stage drawings show currently effective supports rather than final ones. List eccentric-load assumptions and observational differences separately; design and site technical leads confirm the load path before lower excavation proceeds.","failure":"注意干擾：一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A softer arch foot may rotate the lining or redistribute reactions. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-03-k1","title":"驗證方法","titleEn":"Verification method","text":"將拱腳位置、支護形狀與量測變形對到同一斷面，核對左右地層是否支持對稱假設；比較拱腳沉陷與上部收斂的關聯，若反應不對稱，保留偏載情境送設計者審查而非直接取平均。","textEn":"Map arch-foot locations, support shape and measured movement onto one section. Check whether the ground supports symmetry. Compare foot settlement with upper convergence; if behavior is asymmetric, retain eccentric-load scenarios for designer review rather than replacing them with a mean.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-03-k2","title":"現場實務","titleEn":"Site practice","text":"每階段圖面標出當時有效支承而非最終支承，偏載假設與量測差異另列；下半開挖前由設計和現場技術負責人確認荷載路徑。","textEn":"Stage drawings show currently effective supports rather than final ones. List eccentric-load assumptions and observational differences separately; design and site technical leads confirm the load path before lower excavation proceeds.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「上半斷面與反力位置」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Upper section and reaction locations\"?","options":["將拱腳位置、支護形狀與量測變形對到同一斷面，核對左右地層是否支持對稱假設；比較拱腳沉陷與上部收斂的關聯，若反應不對稱，保留偏載情境送設計者審查而非直接取平均。","量測時不必記錄溫度、水頭、開挖序列與施工荷重，因為它們不會影響結果。","多量幾次取平均就能消除任何種類的測量誤差。"],"optionsEn":["Map arch-foot locations, support shape and measured movement onto one section.","Temperature, water head, excavation sequence and construction loads need not be recorded because they cannot affect the result.","Repeating measurements and averaging removes every type of measurement error, including systematic bias."],"answer":0,"explanation":"將拱腳位置、支護形狀與量測變形對到同一斷面，核對左右地層是否支持對稱假設；比較拱腳沉陷與上部收斂的關聯，若反應不對稱，保留偏載情境送設計者審查而非直接取平均。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map arch-foot locations, support shape and measured movement onto one section. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b149-v14-04","title":"上半斷面與反力位置：失效診斷","titleEn":"Upper section and reaction locations: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-03"],"objective":"從症狀倒推「上半斷面與反力位置」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Upper section and reaction locations” and propose discriminating checks, corrective actions and prevention.","instruction":"一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A softer arch foot may rotate the lining or redistribute reactions. Average movement can remain modest while local bending increases. Checking total load alone therefore misses demands caused by unequal support conditions. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。","observationEn":"Link to the mechanism: Checking total load alone therefore misses demands caused by unequal support conditions.","failure":"誤判風險：若相信「總荷載不變就表示左右拱腳需求一定不變。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"An unchanged total load means that demand at each arch foot must also remain unchanged.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-04-k1","title":"失效模式","titleEn":"Failure mode","text":"一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。","textEn":"A softer arch foot may rotate the lining or redistribute reactions. Average movement can remain modest while local bending increases. Checking total load alone therefore misses demands caused by unequal support conditions.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「上半斷面與反力位置」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Upper section and reaction locations\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。","台階長度維持固定就代表每個斷面的受力歷程相同。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","A softer arch foot may rotate the lining or redistribute reactions.","A fixed bench length means that every section experiences an identical loading history."],"answer":1,"explanation":"一側拱腳較軟會使支護旋轉或重新分配反力，總位移平均值可能不大但局部彎矩上升；只核對總荷載會忽略支承差異所引起的細部需求。 需以量測區分可能原因。","explanationEn":"A softer arch foot may rotate the lining or redistribute reactions. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b149-v14-05","title":"台階長度與暴露歷程：機制與系統路徑","titleEn":"Bench length and exposure history: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-04"],"objective":"說明「台階長度與暴露歷程」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Bench length and exposure history” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"上半掌子面到下半支護完成點的距離，代表不同斷面停留於開口狀態的時間歷程。進尺相同但中途停機不同，會形成不同暴露時間，因此台階長度不能單獨替代施工序列和地層時間效應。 假設兩作業點穩定相距12 m、同步平均推進2 m/day，一斷面等待時間12/2=6 days；加入3天停頓則為9 days，非允許等待期。 只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「台階長度與暴露歷程」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The distance from the upper face to completed lower support represents a history of open-section exposure. Equal advance with different shutdown periods produces different exposure times. Bench length alone cannot replace a construction sequence or account for time-dependent ground behavior. Assume two work points remain 12 m apart while advancing at 2 m/day. A section waits 12/2=6 days; a three-day shutdown makes nine days. Neither is an allowable waiting period. Tracking face distance alone misses movement accumulating during shutdown, particularly when a long bench coincides with time-dependent ground. Without timestamps, investigators cannot reconstruct when conditions departed from the original assumptions. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Bench length and exposure history” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「台階長度維持固定就代表每個斷面的受力歷程相同。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A fixed bench length means that every section experiences an identical loading history.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「台階長度與暴露歷程」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Bench length and exposure history”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-05-k1","title":"台階長度與暴露歷程","titleEn":"Bench length and exposure history","text":"上半掌子面到下半支護完成點的距離，代表不同斷面停留於開口狀態的時間歷程。進尺相同但中途停機不同，會形成不同暴露時間，因此台階長度不能單獨替代施工序列和地層時間效應。","textEn":"The distance from the upper face to completed lower support represents a history of open-section exposure. Equal advance with different shutdown periods produces different exposure times.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：台階長度維持固定就代表每個斷面的受力歷程相同。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A fixed bench length means that every section experiences an identical loading history. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「台階長度與暴露歷程」，下列哪一項敘述正確？","questionEn":"Which statement about \"Bench length and exposure history\" is correct?","options":["台階長度維持固定就代表每個斷面的受力歷程相同。","名義拱腳寬度乘長度永遠等於有效接觸面積。","上半掌子面到下半支護完成點的距離，代表不同斷面停留於開口狀態的時間歷程。"],"optionsEn":["A fixed bench length means that every section experiences an identical loading history.","Nominal arch-foot width multiplied by length always equals the effective loaded contact area.","The distance from the upper face to completed lower support represents a history of open-section exposure."],"answer":2,"explanation":"上半掌子面到下半支護完成點的距離，代表不同斷面停留於開口狀態的時間歷程。 其餘選項是常見誤解。","explanationEn":"The distance from the upper face to completed lower support represents a history of open-section exposure. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b149-v14-06","title":"台階長度與暴露歷程：定量估算","titleEn":"Bench length and exposure history: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-05"],"objective":"以數值模型估算「台階長度與暴露歷程」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Bench length and exposure history” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設兩作業點穩定相距12 m、同步平均推進2 m/day，一斷面等待時間12/2=6 days；加入3天停頓則為9 days，非允許等待期。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume two work points remain 12 m apart while advancing at 2 m/day. A section waits 12/2=6 days; a three-day shutdown makes nine days. Neither is an allowable waiting period. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：從各斷面的時間戳重建上半、下半與仰拱完成日期，特別保留停機而無進尺的區間；將這份歷程與收斂曲線比較，確認時間與距離效應是否混淆，不能用班平均進尺補掉長時間缺測。","observationEn":"How to cross-check: Reconstruct upper, lower and invert completion dates for each section using timestamps, preserving stationary shutdown intervals.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設兩作業點穩定相距12 m、同步平均推進2 m/day，一斷面等待時間12/2=6 days；加入3天停頓則為9 days，非允許等待期。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume two work points remain 12 m apart while advancing at 2 m/day. A section waits 12/2=6 days; a three-day shutdown makes nine days. Neither is an allowable waiting period.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「台階長度與暴露歷程」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Bench length and exposure history\", which statement holds?","options":["教學假設，非現場設定或設計允收值。","左右沉陷平均不大就能排除偏轉與接縫問題。","只要每天施工仰拱，最終一定會追上仍前進的掌子面。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","A small average of left and right settlements rules out rotation and joint problems.","Daily invert construction necessarily catches a face that continues advancing at any speed."],"answer":0,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b149-v14-07","title":"台階長度與暴露歷程：試驗與驗證","titleEn":"Bench length and exposure history: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「台階長度與暴露歷程」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Bench length and exposure history” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"從各斷面的時間戳重建上半、下半與仰拱完成日期，特別保留停機而無進尺的區間；將這份歷程與收斂曲線比較，確認時間與距離效應是否混淆，不能用班平均進尺補掉長時間缺測。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconstruct upper, lower and invert completion dates for each section using timestamps, preserving stationary shutdown intervals. Compare this history with convergence and distinguish time from distance effects. Shift-average advance must not be used to fill long gaps in observations. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：施工日誌以斷面編號連結日期和地層，不只保存累計公尺數；延長等待或調整台階時序須由核准審查程序評估，不以算例天數作排程許可。","observationEn":"Site practice: Link dates and ground conditions to section identifiers, not just accumulated meters. Extended waiting or altered bench timing follows the approved review process; classroom durations are not scheduling authorization.","failure":"注意干擾：只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Tracking face distance alone misses movement accumulating during shutdown, particularly when a long bench coincides with time-dependent ground. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-07-k1","title":"驗證方法","titleEn":"Verification method","text":"從各斷面的時間戳重建上半、下半與仰拱完成日期，特別保留停機而無進尺的區間；將這份歷程與收斂曲線比較，確認時間與距離效應是否混淆，不能用班平均進尺補掉長時間缺測。","textEn":"Reconstruct upper, lower and invert completion dates for each section using timestamps, preserving stationary shutdown intervals. Compare this history with convergence and distinguish time from distance effects. Shift-average advance must not be used to fill long gaps in observations.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-07-k2","title":"現場實務","titleEn":"Site practice","text":"施工日誌以斷面編號連結日期和地層，不只保存累計公尺數；延長等待或調整台階時序須由核准審查程序評估，不以算例天數作排程許可。","textEn":"Link dates and ground conditions to section identifiers, not just accumulated meters. Extended waiting or altered bench timing follows the approved review process; classroom durations are not scheduling authorization.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「台階長度與暴露歷程」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Bench length and exposure history\"?","options":["沿用另一條隧道或另一處地層的量測結果，就可視為本工程已完成驗證。","從各斷面的時間戳重建上半、下半與仰拱完成日期，特別保留停機而無進尺的區間；將這份歷程與收斂曲線比較，確認時間與距離效應是否混淆，不能用班平均進尺補掉長時間缺測。","只要排水設備足夠大，增加湧水就不需要地工判讀。"],"optionsEn":["Reusing results from another tunnel or ground formation counts as verifying this structure.","Reconstruct upper, lower and invert completion dates for each section using timestamps, preserving stationary shutdown intervals.","Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review."],"answer":1,"explanation":"從各斷面的時間戳重建上半、下半與仰拱完成日期，特別保留停機而無進尺的區間；將這份歷程與收斂曲線比較，確認時間與距離效應是否混淆，不能用班平均進尺補掉長時間缺測。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconstruct upper, lower and invert completion dates for each section using timestamps, preserving stationary shutdown intervals. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b149-v14-08","title":"台階長度與暴露歷程：失效診斷","titleEn":"Bench length and exposure history: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-07"],"objective":"從症狀倒推「台階長度與暴露歷程」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Bench length and exposure history” and propose discriminating checks, corrective actions and prevention.","instruction":"只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Tracking face distance alone misses movement accumulating during shutdown, particularly when a long bench coincides with time-dependent ground. Without timestamps, investigators cannot reconstruct when conditions departed from the original assumptions. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。","observationEn":"Link to the mechanism: Without timestamps, investigators cannot reconstruct when conditions departed from the original assumptions.","failure":"誤判風險：若相信「台階長度維持固定就代表每個斷面的受力歷程相同。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A fixed bench length means that every section experiences an identical loading history.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-08-k1","title":"失效模式","titleEn":"Failure mode","text":"只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。","textEn":"Tracking face distance alone misses movement accumulating during shutdown, particularly when a long bench coincides with time-dependent ground. Without timestamps, investigators cannot reconstruct when conditions departed from the original assumptions.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「台階長度與暴露歷程」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Bench length and exposure history\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","名義拱腳寬度乘長度永遠等於有效接觸面積。","只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Nominal arch-foot width multiplied by length always equals the effective loaded contact area.","Tracking face distance alone misses movement accumulating during shutdown, particularly when a long bench coincides with time-dependent ground."],"answer":2,"explanation":"只追蹤掌子面距離會忽略停機期間的變形累積，長台階與時間相依地層疊加時尤其明顯；資料缺少時間戳便無法回溯何時偏離原假設。 需以量測區分可能原因。","explanationEn":"Tracking face distance alone misses movement accumulating during shutdown, particularly when a long bench coincides with time-dependent ground. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b149-v14-s2","title":"機制、材料與定量設計","titleEn":"Mechanisms, materials and quantitative design","description":"本階段聚焦「拱腳面積與接觸承壓」與「保留核心與幾何邊界」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Arch-foot area and contact bearing\" and \"Retained core and geometric boundaries\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b149-v14-09","title":"拱腳面積與接觸承壓：機制與系統路徑","titleEn":"Arch-foot area and contact bearing: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-08"],"objective":"說明「拱腳面積與接觸承壓」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Arch-foot area and contact bearing” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"拱腳把集中反力傳到地層或暫時基座，名義寬度不一定等於有效接觸寬度。接觸不平、偏心與局部軟弱層會改變壓力分布，平均承壓只能作為追問接觸機制的起點。 假設反力R=600 kN、有效接觸A=1.2 m²，平均q=500 kPa；若接觸降為0.8 m²，q=750 kPa，未檢查地層承載或沉陷。 基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「拱腳面積與接觸承壓」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"An arch foot transfers concentrated reaction to ground or a temporary base, and nominal width may differ from effective contact. Uneven seating, eccentricity and weak seams alter pressure distribution. Mean bearing is only the starting point for examining that mechanism. Assume reaction R=600 kN and effective contact A=1.2 m². Mean bearing q=500 kPa; with A=0.8 m² it becomes 750 kPa, without checking ground capacity or settlement. Local erosion or softening can reduce effective footing contact and cause settlement at unchanged total reaction. When the contact is hidden, inspecting only the upper lining delays recognition of the changed bearing path below it. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Arch-foot area and contact bearing” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「名義拱腳寬度乘長度永遠等於有效接觸面積。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Nominal arch-foot width multiplied by length always equals the effective loaded contact area.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「拱腳面積與接觸承壓」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Arch-foot area and contact bearing”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-09-k1","title":"拱腳面積與接觸承壓","titleEn":"Arch-foot area and contact bearing","text":"拱腳把集中反力傳到地層或暫時基座，名義寬度不一定等於有效接觸寬度。接觸不平、偏心與局部軟弱層會改變壓力分布，平均承壓只能作為追問接觸機制的起點。","textEn":"An arch foot transfers concentrated reaction to ground or a temporary base, and nominal width may differ from effective contact. Uneven seating, eccentricity and weak seams alter pressure distribution.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：名義拱腳寬度乘長度永遠等於有效接觸面積。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Nominal arch-foot width multiplied by length always equals the effective loaded contact area. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「拱腳面積與接觸承壓」，下列哪一項敘述正確？","questionEn":"Which statement about \"Arch-foot area and contact bearing\" is correct?","options":["拱腳把集中反力傳到地層或暫時基座，名義寬度不一定等於有效接觸寬度。","名義拱腳寬度乘長度永遠等於有效接觸面積。","核心保留體積比例就是它提供的抗力比例。"],"optionsEn":["An arch foot transfers concentrated reaction to ground or a temporary base, and nominal width may differ from effective contact.","Nominal arch-foot width multiplied by length always equals the effective loaded contact area.","The retained core volume percentage equals the percentage of resistance it provides."],"answer":0,"explanation":"拱腳把集中反力傳到地層或暫時基座，名義寬度不一定等於有效接觸寬度。 其餘選項是常見誤解。","explanationEn":"An arch foot transfers concentrated reaction to ground or a temporary base, and nominal width may differ from effective contact. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b149-v14-10","title":"拱腳面積與接觸承壓：定量估算","titleEn":"Arch-foot area and contact bearing: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-09"],"objective":"以數值模型估算「拱腳面積與接觸承壓」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Arch-foot area and contact bearing” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設反力R=600 kN、有效接觸A=1.2 m²，平均q=500 kPa；若接觸降為0.8 m²，q=750 kPa，未檢查地層承載或沉陷。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume reaction R=600 kN and effective contact A=1.2 m². Mean bearing q=500 kPa; with A=0.8 m² it becomes 750 kPa, without checking ground capacity or settlement. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對竣工接觸尺寸、地層描述及拱腳沉陷，將偏心與接觸缺口畫在同一圖上；必要試驗須代表實際材料和受力方向，不能把其他位置的承載數字直接移用，異常由基礎與支護設計者審查。","observationEn":"How to cross-check: Check as-built contact dimensions, ground descriptions and arch-foot settlement, mapping eccentricity and gaps together.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設反力R=600 kN、有效接觸A=1.2 m²，平均q=500 kPa；若接觸降為0.8 m²，q=750 kPa，未檢查地層承載或沉陷。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume reaction R=600 kN and effective contact A=1.2 m². Mean bearing q=500 kPa; with A=0.8 m² it becomes 750 kPa, without checking ground capacity or settlement.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「拱腳面積與接觸承壓」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Arch-foot area and contact bearing\", which statement holds?","options":["出碴重量和幾何量不符時，只要修改密度就能解決。","教學假設，非現場設定或設計允收值。","多量幾次取平均就能消除任何種類的測量誤差。"],"optionsEn":["Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.","Teaching assumptions, not operating settings or design acceptance limits.","Repeating measurements and averaging removes every type of measurement error, including systematic bias."],"answer":1,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b149-v14-11","title":"拱腳面積與接觸承壓：試驗與驗證","titleEn":"Arch-foot area and contact bearing: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「拱腳面積與接觸承壓」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Arch-foot area and contact bearing” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對竣工接觸尺寸、地層描述及拱腳沉陷，將偏心與接觸缺口畫在同一圖上；必要試驗須代表實際材料和受力方向，不能把其他位置的承載數字直接移用，異常由基礎與支護設計者審查。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check as-built contact dimensions, ground descriptions and arch-foot settlement, mapping eccentricity and gaps together. Supporting tests must represent the actual material and loading direction. Do not transplant a capacity value from another location; foundation and support designers review anomalies. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：拱腳交接記錄包含接觸條件和地下水變化，未知面積以範圍呈現；支承處置由設計者核准，平均承壓計算不作現場加載依據。","observationEn":"Site practice: Arch-foot handover records include contact conditions and groundwater changes, expressing uncertain area as a range. The designer approves support treatment; average-pressure calculations do not authorize field loading.","failure":"注意干擾：基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Local erosion or softening can reduce effective footing contact and cause settlement at unchanged total reaction. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-11-k1","title":"驗證方法","titleEn":"Verification method","text":"核對竣工接觸尺寸、地層描述及拱腳沉陷，將偏心與接觸缺口畫在同一圖上；必要試驗須代表實際材料和受力方向，不能把其他位置的承載數字直接移用，異常由基礎與支護設計者審查。","textEn":"Check as-built contact dimensions, ground descriptions and arch-foot settlement, mapping eccentricity and gaps together. Supporting tests must represent the actual material and loading direction. Do not transplant a capacity value from another location; foundation and support designers review anomalies.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-11-k2","title":"現場實務","titleEn":"Site practice","text":"拱腳交接記錄包含接觸條件和地下水變化，未知面積以範圍呈現；支承處置由設計者核准，平均承壓計算不作現場加載依據。","textEn":"Arch-foot handover records include contact conditions and groundwater changes, expressing uncertain area as a range. The designer approves support treatment; average-pressure calculations do not authorize field loading.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「拱腳面積與接觸承壓」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Arch-foot area and contact bearing\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","平均斷面尺寸合格就表示所有淨空介面都合格。","核對竣工接觸尺寸、地層描述及拱腳沉陷，將偏心與接觸缺口畫在同一圖上。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Acceptable average section dimensions guarantee that every clearance interface is acceptable.","Check as-built contact dimensions, ground descriptions and arch-foot settlement, mapping eccentricity and gaps together."],"answer":2,"explanation":"核對竣工接觸尺寸、地層描述及拱腳沉陷，將偏心與接觸缺口畫在同一圖上；必要試驗須代表實際材料和受力方向，不能把其他位置的承載數字直接移用，異常由基礎與支護設計者審查。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check as-built contact dimensions, ground descriptions and arch-foot settlement, mapping eccentricity and gaps together. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b149-v14-12","title":"拱腳面積與接觸承壓：失效診斷","titleEn":"Arch-foot area and contact bearing: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-11"],"objective":"從症狀倒推「拱腳面積與接觸承壓」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Arch-foot area and contact bearing” and propose discriminating checks, corrective actions and prevention.","instruction":"基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Local erosion or softening can reduce effective footing contact and cause settlement at unchanged total reaction. When the contact is hidden, inspecting only the upper lining delays recognition of the changed bearing path below it. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。","observationEn":"Link to the mechanism: When the contact is hidden, inspecting only the upper lining delays recognition of the changed bearing path below it.","failure":"誤判風險：若相信「名義拱腳寬度乘長度永遠等於有效接觸面積。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Nominal arch-foot width multiplied by length always equals the effective loaded contact area.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-12-k1","title":"失效模式","titleEn":"Failure mode","text":"基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。","textEn":"Local erosion or softening can reduce effective footing contact and cause settlement at unchanged total reaction. When the contact is hidden, inspecting only the upper lining delays recognition of the changed bearing path below it.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「拱腳面積與接觸承壓」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Arch-foot area and contact bearing\" shows distress, which diagnosis is most reasonable?","options":["基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","核心保留體積比例就是它提供的抗力比例。"],"optionsEn":["Local erosion or softening can reduce effective footing contact and cause settlement at unchanged total reaction.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","The retained core volume percentage equals the percentage of resistance it provides."],"answer":0,"explanation":"基座局部沖刷或軟化使有效面積縮小，支護可能在總反力不變時產生額外沉陷；若外觀遮蔽接觸面，僅看上部襯砌會延後發現承載路徑的變化。 需以量測區分可能原因。","explanationEn":"Local erosion or softening can reduce effective footing contact and cause settlement at unchanged total reaction. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b149-v14-13","title":"保留核心與幾何邊界：機制與系統路徑","titleEn":"Retained core and geometric boundaries: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-12"],"objective":"說明「保留核心與幾何邊界」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Retained core and geometric boundaries” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"保留核心可改變開挖面的幾何與約束，但其力學作用取決於材料連續性、含水和與周圍地層的連接。體積占比只是幾何指標，不能直接換算成支護力或穩定儲備。 假設整段面積60 m²、長4 m，總體積240 m³；保留核心面積12 m²同長，體積48 m³，占20%，未代表提供20%抗力。 核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「保留核心與幾何邊界」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A retained core changes excavation geometry and restraint, but its mechanical contribution depends on continuity, water and connection to surrounding ground. Its volume fraction is a geometric indicator rather than a direct measure of support force or stability reserve. Assume total area 60 m² over 4 m, giving 240 m³. A retained core of 12 m² over the same length occupies 48 m³ or 20%, which does not mean it supplies 20% resistance. A core can lose continuity through disturbance or seepage while retaining its outline. Treating visible volume as effective support misses internal degradation, and the load transfer during later removal may differ from the original model. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Retained core and geometric boundaries” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「核心保留體積比例就是它提供的抗力比例。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The retained core volume percentage equals the percentage of resistance it provides.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「保留核心與幾何邊界」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Retained core and geometric boundaries”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-13-k1","title":"保留核心與幾何邊界","titleEn":"Retained core and geometric boundaries","text":"保留核心可改變開挖面的幾何與約束，但其力學作用取決於材料連續性、含水和與周圍地層的連接。體積占比只是幾何指標，不能直接換算成支護力或穩定儲備。","textEn":"A retained core changes excavation geometry and restraint, but its mechanical contribution depends on continuity, water and connection to surrounding ground. Its volume fraction is a geometric indicator rather than a direct measure of support force or stability reserve.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：核心保留體積比例就是它提供的抗力比例。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The retained core volume percentage equals the percentage of resistance it provides. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「保留核心與幾何邊界」，下列哪一項敘述正確？","questionEn":"Which statement about \"Retained core and geometric boundaries\" is correct?","options":["核心保留體積比例就是它提供的抗力比例。","保留核心可改變開挖面的幾何與約束，但其力學作用取決於材料連續性、含水和與周圍地層的連接。","左右沉陷平均不大就能排除偏轉與接縫問題。"],"optionsEn":["The retained core volume percentage equals the percentage of resistance it provides.","A retained core changes excavation geometry and restraint, but its mechanical contribution depends on continuity, water and connection to surrounding ground.","A small average of left and right settlements rules out rotation and joint problems."],"answer":1,"explanation":"保留核心可改變開挖面的幾何與約束，但其力學作用取決於材料連續性、含水和與周圍地層的連接。 其餘選項是常見誤解。","explanationEn":"A retained core changes excavation geometry and restraint, but its mechanical contribution depends on continuity, water and connection to surrounding ground. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b149-v14-14","title":"保留核心與幾何邊界：定量估算","titleEn":"Retained core and geometric boundaries: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-13"],"objective":"以數值模型估算「保留核心與幾何邊界」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Retained core and geometric boundaries” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設整段面積60 m²、長4 m，總體積240 m³；保留核心面積12 m²同長，體積48 m³，占20%，未代表提供20%抗力。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume total area 60 m² over 4 m, giving 240 m³. A retained core of 12 m² over the same length occupies 48 m³ or 20%, which does not mean it supplies 20% resistance. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將核心實際輪廓、裂隙及含水狀態與階段圖比對，核對是否有局部先行移除或被設備擾動；若幾何符合而材料明顯改變，仍需重新檢查作用假設，不能只憑剩餘土量宣稱支承有效。","observationEn":"How to cross-check: Compare actual core geometry, fractures and moisture with stage drawings.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設整段面積60 m²、長4 m，總體積240 m³；保留核心面積12 m²同長，體積48 m³，占20%，未代表提供20%抗力。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume total area 60 m² over 4 m, giving 240 m³. A retained core of 12 m² over the same length occupies 48 m³ or 20%, which does not mean it supplies 20% resistance.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「保留核心與幾何邊界」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Retained core and geometric boundaries\", which statement holds?","options":["只要每天施工仰拱，最終一定會追上仍前進的掌子面。","只要排水設備足夠大，增加湧水就不需要地工判讀。","教學假設，非現場設定或設計允收值。"],"optionsEn":["Daily invert construction necessarily catches a face that continues advancing at any speed.","Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b149-v14-15","title":"保留核心與幾何邊界：試驗與驗證","titleEn":"Retained core and geometric boundaries: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「保留核心與幾何邊界」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Retained core and geometric boundaries” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將核心實際輪廓、裂隙及含水狀態與階段圖比對，核對是否有局部先行移除或被設備擾動；若幾何符合而材料明顯改變，仍需重新檢查作用假設，不能只憑剩餘土量宣稱支承有效。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare actual core geometry, fractures and moisture with stage drawings. Check for premature local removal or equipment disturbance. Even with correct geometry, changed material requires reassessment of its assumed function; retained quantity alone cannot demonstrate effective restraint. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：核心記錄同時標示形狀與材料狀態，移除前列出替代支承及核准停點；由地工與施工技術主管確認條件，課堂體積比不構成拆除授權。","observationEn":"Site practice: Core records show both shape and material condition. Before removal, list replacement restraint and the approved hold point. Geotechnical and construction leads confirm conditions; the classroom volume ratio does not authorize removal.","failure":"注意干擾：核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A core can lose continuity through disturbance or seepage while retaining its outline. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-15-k1","title":"驗證方法","titleEn":"Verification method","text":"將核心實際輪廓、裂隙及含水狀態與階段圖比對，核對是否有局部先行移除或被設備擾動；若幾何符合而材料明顯改變，仍需重新檢查作用假設，不能只憑剩餘土量宣稱支承有效。","textEn":"Compare actual core geometry, fractures and moisture with stage drawings. Check for premature local removal or equipment disturbance. Even with correct geometry, changed material requires reassessment of its assumed function; retained quantity alone cannot demonstrate effective restraint.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-15-k2","title":"現場實務","titleEn":"Site practice","text":"核心記錄同時標示形狀與材料狀態，移除前列出替代支承及核准停點；由地工與施工技術主管確認條件，課堂體積比不構成拆除授權。","textEn":"Core records show both shape and material condition. Before removal, list replacement restraint and the approved hold point. Geotechnical and construction leads confirm conditions; the classroom volume ratio does not authorize removal.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「保留核心與幾何邊界」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Retained core and geometric boundaries\"?","options":["將核心實際輪廓、裂隙及含水狀態與階段圖比對，核對是否有局部先行移除或被設備擾動；若幾何符合而材料明顯改變，仍需重新檢查作用假設，不能只憑剩餘土量宣稱支承有效。","不確定度太難估計，報告中只寫最佳值即可。","總荷載不變就表示左右拱腳需求一定不變。"],"optionsEn":["Compare actual core geometry, fractures and moisture with stage drawings.","Uncertainty is too hard to estimate, so the report may state only the best value.","An unchanged total load means that demand at each arch foot must also remain unchanged."],"answer":0,"explanation":"將核心實際輪廓、裂隙及含水狀態與階段圖比對，核對是否有局部先行移除或被設備擾動；若幾何符合而材料明顯改變，仍需重新檢查作用假設，不能只憑剩餘土量宣稱支承有效。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare actual core geometry, fractures and moisture with stage drawings. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b149-v14-16","title":"保留核心與幾何邊界：失效診斷","titleEn":"Retained core and geometric boundaries: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-15"],"objective":"從症狀倒推「保留核心與幾何邊界」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Retained core and geometric boundaries” and propose discriminating checks, corrective actions and prevention.","instruction":"核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A core can lose continuity through disturbance or seepage while retaining its outline. Treating visible volume as effective support misses internal degradation, and the load transfer during later removal may differ from the original model. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。","observationEn":"Link to the mechanism: Treating visible volume as effective support misses internal degradation, and the load transfer during later removal may differ from the original model.","failure":"誤判風險：若相信「核心保留體積比例就是它提供的抗力比例。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The retained core volume percentage equals the percentage of resistance it provides.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-16-k1","title":"失效模式","titleEn":"Failure mode","text":"核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。","textEn":"A core can lose continuity through disturbance or seepage while retaining its outline. Treating visible volume as effective support misses internal degradation, and the load transfer during later removal may differ from the original model.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「保留核心與幾何邊界」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Retained core and geometric boundaries\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。","左右沉陷平均不大就能排除偏轉與接縫問題。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","A core can lose continuity through disturbance or seepage while retaining its outline.","A small average of left and right settlements rules out rotation and joint problems."],"answer":1,"explanation":"核心受到鬆動或滲水侵蝕而失去連續性，外形仍可能維持；把外觀體積當成有效支護會忽略內部變質，後續移除時的荷載轉移也可能和原模型不同。 需以量測區分可能原因。","explanationEn":"A core can lose continuity through disturbance or seepage while retaining its outline. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b149-v14-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「左右下挖與差異沉陷」與「開挖與出碴質量帳」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Asymmetric lower excavation and settlement\" and \"Excavation and muck mass accounting\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b149-v14-17","title":"左右下挖與差異沉陷：機制與系統路徑","titleEn":"Asymmetric lower excavation and settlement: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-16"],"objective":"說明「左右下挖與差異沉陷」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Asymmetric lower excavation and settlement” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"左右下半開挖不同步會改變拱腳的支承與變形，差異沉陷可能令上部支護旋轉。小角度幾何能量化姿態差，卻沒有計入襯砌彎曲、地層再分配和接縫變形，需連結結構模型判讀。 假設左右拱腳相距6 m、沉陷差4 mm=0.004 m，剛體小轉角θ≈0.004/6=0.000667 rad=0.0382°，並非容許變形值。 一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「左右下挖與差異沉陷」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Uneven progress on the lower sides changes arch-foot support and movement. Differential settlement can rotate the upper lining. Small-angle geometry quantifies attitude but omits lining bending, ground redistribution and joint deformation, which need structural interpretation. Assume feet are 6 m apart with differential settlement 4 mm=0.004 m. Rigid-body small rotation θ≈0.004/6=0.000667 rad=0.0382°, not an allowable deformation. If one foot loses its previous support first, differential settlement can enlarge joint openings. A report retaining only the left-right mean cancels the contrast numerically and hides rotation and localized deformation from review. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Asymmetric lower excavation and settlement” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「左右沉陷平均不大就能排除偏轉與接縫問題。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A small average of left and right settlements rules out rotation and joint problems.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「左右下挖與差異沉陷」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Asymmetric lower excavation and settlement”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-17-k1","title":"左右下挖與差異沉陷","titleEn":"Asymmetric lower excavation and settlement","text":"左右下半開挖不同步會改變拱腳的支承與變形，差異沉陷可能令上部支護旋轉。小角度幾何能量化姿態差，卻沒有計入襯砌彎曲、地層再分配和接縫變形，需連結結構模型判讀。","textEn":"Uneven progress on the lower sides changes arch-foot support and movement. Differential settlement can rotate the upper lining.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：左右沉陷平均不大就能排除偏轉與接縫問題。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A small average of left and right settlements rules out rotation and joint problems. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「左右下挖與差異沉陷」，下列哪一項敘述正確？","questionEn":"Which statement about \"Asymmetric lower excavation and settlement\" is correct?","options":["左右沉陷平均不大就能排除偏轉與接縫問題。","出碴重量和幾何量不符時，只要修改密度就能解決。","左右下半開挖不同步會改變拱腳的支承與變形，差異沉陷可能令上部支護旋轉。"],"optionsEn":["A small average of left and right settlements rules out rotation and joint problems.","Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.","Uneven progress on the lower sides changes arch-foot support and movement."],"answer":2,"explanation":"左右下半開挖不同步會改變拱腳的支承與變形，差異沉陷可能令上部支護旋轉。 其餘選項是常見誤解。","explanationEn":"Uneven progress on the lower sides changes arch-foot support and movement. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b149-v14-18","title":"左右下挖與差異沉陷：定量估算","titleEn":"Asymmetric lower excavation and settlement: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-17"],"objective":"以數值模型估算「左右下挖與差異沉陷」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Asymmetric lower excavation and settlement” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設左右拱腳相距6 m、沉陷差4 mm=0.004 m，剛體小轉角θ≈0.004/6=0.000667 rad=0.0382°，並非容許變形值。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume feet are 6 m apart with differential settlement 4 mm=0.004 m. Rigid-body small rotation θ≈0.004/6=0.000667 rad=0.0382°, not an allowable deformation. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：使用共同穩定基準量測兩側高程與拱頂位置，對齊左右開挖和支護時間；比較剛體轉動預測與實際斷面畸變，若二者不符須檢討彎曲或接縫機制，不把所有差異都視為儀器誤差。","observationEn":"How to cross-check: Measure both foot levels and crown position from a common stable reference, aligning left-right excavation and support times.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設左右拱腳相距6 m、沉陷差4 mm=0.004 m，剛體小轉角θ≈0.004/6=0.000667 rad=0.0382°，並非容許變形值。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume feet are 6 m apart with differential settlement 4 mm=0.004 m. Rigid-body small rotation θ≈0.004/6=0.000667 rad=0.0382°, not an allowable deformation.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「左右下挖與差異沉陷」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Asymmetric lower excavation and settlement\", which statement holds?","options":["教學假設，非現場設定或設計允收值。","多量幾次取平均就能消除任何種類的測量誤差。","平均斷面尺寸合格就表示所有淨空介面都合格。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","Repeating measurements and averaging removes every type of measurement error, including systematic bias.","Acceptable average section dimensions guarantee that every clearance interface is acceptable."],"answer":0,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b149-v14-19","title":"左右下挖與差異沉陷：試驗與驗證","titleEn":"Asymmetric lower excavation and settlement: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「左右下挖與差異沉陷」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Asymmetric lower excavation and settlement” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"使用共同穩定基準量測兩側高程與拱頂位置，對齊左右開挖和支護時間；比較剛體轉動預測與實際斷面畸變，若二者不符須檢討彎曲或接縫機制，不把所有差異都視為儀器誤差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure both foot levels and crown position from a common stable reference, aligning left-right excavation and support times. Compare rigid rotation with actual section distortion. Differences require reviewing bending or joint mechanisms rather than assigning all disagreement to instrumentation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：量測報表同時呈現左右值、差值與平均值，保留階段圖版本；任何非對稱序列變更須核對暫時支承，由結構與施工負責人共同核准。","observationEn":"Site practice: Monitoring reports show left, right, difference and mean values alongside drawing versions. Any asymmetric sequence change requires review of temporary support and joint approval by structural and construction leads.","failure":"注意干擾：一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: If one foot loses its previous support first, differential settlement can enlarge joint openings. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-19-k1","title":"驗證方法","titleEn":"Verification method","text":"使用共同穩定基準量測兩側高程與拱頂位置，對齊左右開挖和支護時間；比較剛體轉動預測與實際斷面畸變，若二者不符須檢討彎曲或接縫機制，不把所有差異都視為儀器誤差。","textEn":"Measure both foot levels and crown position from a common stable reference, aligning left-right excavation and support times. Compare rigid rotation with actual section distortion. Differences require reviewing bending or joint mechanisms rather than assigning all disagreement to instrumentation.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-19-k2","title":"現場實務","titleEn":"Site practice","text":"量測報表同時呈現左右值、差值與平均值，保留階段圖版本；任何非對稱序列變更須核對暫時支承，由結構與施工負責人共同核准。","textEn":"Monitoring reports show left, right, difference and mean values alongside drawing versions. Any asymmetric sequence change requires review of temporary support and joint approval by structural and construction leads.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「左右下挖與差異沉陷」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Asymmetric lower excavation and settlement\"?","options":["允收準則可以等看到量測數據後再決定。","使用共同穩定基準量測兩側高程與拱頂位置，對齊左右開挖和支護時間；比較剛體轉動預測與實際斷面畸變，若二者不符須檢討彎曲或接縫機制，不把所有差異都視為儀器誤差。","台階長度維持固定就代表每個斷面的受力歷程相同。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Measure both foot levels and crown position from a common stable reference, aligning left-right excavation and support times.","A fixed bench length means that every section experiences an identical loading history."],"answer":1,"explanation":"使用共同穩定基準量測兩側高程與拱頂位置，對齊左右開挖和支護時間；比較剛體轉動預測與實際斷面畸變，若二者不符須檢討彎曲或接縫機制，不把所有差異都視為儀器誤差。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure both foot levels and crown position from a common stable reference, aligning left-right excavation and support times. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b149-v14-20","title":"左右下挖與差異沉陷：失效診斷","titleEn":"Asymmetric lower excavation and settlement: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-19"],"objective":"從症狀倒推「左右下挖與差異沉陷」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Asymmetric lower excavation and settlement” and propose discriminating checks, corrective actions and prevention.","instruction":"一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"If one foot loses its previous support first, differential settlement can enlarge joint openings. A report retaining only the left-right mean cancels the contrast numerically and hides rotation and localized deformation from review. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。","observationEn":"Link to the mechanism: A report retaining only the left-right mean cancels the contrast numerically and hides rotation and localized deformation from review.","failure":"誤判風險：若相信「左右沉陷平均不大就能排除偏轉與接縫問題。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A small average of left and right settlements rules out rotation and joint problems.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-20-k1","title":"失效模式","titleEn":"Failure mode","text":"一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。","textEn":"If one foot loses its previous support first, differential settlement can enlarge joint openings. A report retaining only the left-right mean cancels the contrast numerically and hides rotation and localized deformation from review.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「左右下挖與差異沉陷」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Asymmetric lower excavation and settlement\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","出碴重量和幾何量不符時，只要修改密度就能解決。","一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.","If one foot loses its previous support first, differential settlement can enlarge joint openings."],"answer":2,"explanation":"一側拱腳在下挖時先失去原支承，差異沉陷可放大接縫開口；如果報表只保留左右平均值，旋轉和局部變形便被相互抵消而看不見。 需以量測區分可能原因。","explanationEn":"If one foot loses its previous support first, differential settlement can enlarge joint openings. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b149-v14-21","title":"開挖與出碴質量帳：機制與系統路徑","titleEn":"Excavation and muck mass accounting: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-20"],"objective":"說明「開挖與出碴質量帳」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Excavation and muck mass accounting” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"台階分部工程量需以相同區間和體積基準對照出碴質量，含水量和密度變化會影響換算。物料帳可發現遺漏區段或超挖線索，但它不能獨立分辨掉塊、密度偏差與稱重誤差。 假設下半面積25 m²、進尺1.5 m、原位密度2400 kg/m³，質量25×1.5×2400=90000 kg=90 t；假設鬆方係數1.4時體積為52.5 m³。 混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「開挖與出碴質量帳」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Bench quantities must match muck mass over the same interval and volume basis. Moisture and density changes influence conversion. Material accounting can flag missing intervals or potential overbreak, but cannot by itself distinguish rock falls, density bias and weighing error. Assume lower area 25 m², advance 1.5 m and in-situ density 2400 kg/m³. Mass is 90000 kg=90 t. With assumed bulking factor 1.4, loose volume is 52.5 m³. Counting a mixed vehicle in both upper and lower records falsely reports overbreak and distorts ground interpretation. Conversely, assigning every unexplained difference to density may hide genuine profile excess and localized ground loss. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Excavation and muck mass accounting” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「出碴重量和幾何量不符時，只要修改密度就能解決。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「開挖與出碴質量帳」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Excavation and muck mass accounting”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-21-k1","title":"開挖與出碴質量帳","titleEn":"Excavation and muck mass accounting","text":"台階分部工程量需以相同區間和體積基準對照出碴質量，含水量和密度變化會影響換算。物料帳可發現遺漏區段或超挖線索，但它不能獨立分辨掉塊、密度偏差與稱重誤差。","textEn":"Bench quantities must match muck mass over the same interval and volume basis. Moisture and density changes influence conversion.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：出碴重量和幾何量不符時，只要修改密度就能解決。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Whenever muck mass and geometry disagree, changing the assumed density resolves the problem. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「開挖與出碴質量帳」，下列哪一項敘述正確？","questionEn":"Which statement about \"Excavation and muck mass accounting\" is correct?","options":["台階分部工程量需以相同區間和體積基準對照出碴質量，含水量和密度變化會影響換算。","出碴重量和幾何量不符時，只要修改密度就能解決。","只要每天施工仰拱，最終一定會追上仍前進的掌子面。"],"optionsEn":["Bench quantities must match muck mass over the same interval and volume basis.","Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.","Daily invert construction necessarily catches a face that continues advancing at any speed."],"answer":0,"explanation":"台階分部工程量需以相同區間和體積基準對照出碴質量，含水量和密度變化會影響換算。 其餘選項是常見誤解。","explanationEn":"Bench quantities must match muck mass over the same interval and volume basis. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b149-v14-22","title":"開挖與出碴質量帳：定量估算","titleEn":"Excavation and muck mass accounting: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-21"],"objective":"以數值模型估算「開挖與出碴質量帳」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Excavation and muck mass accounting” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設下半面積25 m²、進尺1.5 m、原位密度2400 kg/m³，質量25×1.5×2400=90000 kg=90 t；假設鬆方係數1.4時體積為52.5 m³。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume lower area 25 m², advance 1.5 m and in-situ density 2400 kg/m³. Mass is 90000 kg=90 t. With assumed bulking factor 1.4, loose volume is 52.5 m³. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：對齊斷面掃描、進尺與車次稱重，單獨扣列可辨識的其他物料及水分變化；檢查資料是否跨越上下台階混裝，未能分離時應標明估計範圍，不能用調整密度的方式強迫帳目相等。","observationEn":"How to cross-check: Align section scans, advance and vehicle weights, separately accounting for identifiable other material and moisture changes.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設下半面積25 m²、進尺1.5 m、原位密度2400 kg/m³，質量25×1.5×2400=90000 kg=90 t；假設鬆方係數1.4時體積為52.5 m³。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume lower area 25 m², advance 1.5 m and in-situ density 2400 kg/m³. Mass is 90000 kg=90 t. With assumed bulking factor 1.4, loose volume is 52.5 m³.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「開挖與出碴質量帳」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Excavation and muck mass accounting\", which statement holds?","options":["只要排水設備足夠大，增加湧水就不需要地工判讀。","教學假設，非現場設定或設計允收值。","總荷載不變就表示左右拱腳需求一定不變。"],"optionsEn":["Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.","Teaching assumptions, not operating settings or design acceptance limits.","An unchanged total load means that demand at each arch foot must also remain unchanged."],"answer":1,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b149-v14-23","title":"開挖與出碴質量帳：試驗與驗證","titleEn":"Excavation and muck mass accounting: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「開挖與出碴質量帳」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Excavation and muck mass accounting” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"對齊斷面掃描、進尺與車次稱重，單獨扣列可辨識的其他物料及水分變化；檢查資料是否跨越上下台階混裝，未能分離時應標明估計範圍，不能用調整密度的方式強迫帳目相等。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Align section scans, advance and vehicle weights, separately accounting for identifiable other material and moisture changes. Check whether upper and lower muck was mixed. If separation is impossible, state an estimated range instead of adjusting density until the accounts agree. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保留原始稱重與分部歸屬，未解差額由測量、地質和運輸人員共同追查；工程量結算與穩定判斷分開，避免為配平帳目而移除異常證據。","observationEn":"Site practice: Retain original weights and subdivision assignments. Survey, geological and transport staff jointly investigate unresolved differences, separating quantity settlement from stability assessment so accounting adjustments do not erase anomaly evidence.","failure":"注意干擾：混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Counting a mixed vehicle in both upper and lower records falsely reports overbreak and distorts ground interpretation. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-23-k1","title":"驗證方法","titleEn":"Verification method","text":"對齊斷面掃描、進尺與車次稱重，單獨扣列可辨識的其他物料及水分變化；檢查資料是否跨越上下台階混裝，未能分離時應標明估計範圍，不能用調整密度的方式強迫帳目相等。","textEn":"Align section scans, advance and vehicle weights, separately accounting for identifiable other material and moisture changes. Check whether upper and lower muck was mixed. If separation is impossible, state an estimated range instead of adjusting density until the accounts agree.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-23-k2","title":"現場實務","titleEn":"Site practice","text":"保留原始稱重與分部歸屬，未解差額由測量、地質和運輸人員共同追查；工程量結算與穩定判斷分開，避免為配平帳目而移除異常證據。","textEn":"Retain original weights and subdivision assignments. Survey, geological and transport staff jointly investigate unresolved differences, separating quantity settlement from stability assessment so accounting adjustments do not erase anomaly evidence.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「開挖與出碴質量帳」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Excavation and muck mass accounting\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","名義拱腳寬度乘長度永遠等於有效接觸面積。","對齊斷面掃描、進尺與車次稱重，單獨扣列可辨識的其他物料及水分變化；檢查資料是否跨越上下台階混裝，未能分離時應標明估計範圍，不能用調整密度的方式強迫帳目相等。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Nominal arch-foot width multiplied by length always equals the effective loaded contact area.","Align section scans, advance and vehicle weights, separately accounting for identifiable other material and moisture changes."],"answer":2,"explanation":"對齊斷面掃描、進尺與車次稱重，單獨扣列可辨識的其他物料及水分變化；檢查資料是否跨越上下台階混裝，未能分離時應標明估計範圍，不能用調整密度的方式強迫帳目相等。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Align section scans, advance and vehicle weights, separately accounting for identifiable other material and moisture changes. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b149-v14-24","title":"開挖與出碴質量帳：失效診斷","titleEn":"Excavation and muck mass accounting: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-23"],"objective":"從症狀倒推「開挖與出碴質量帳」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Excavation and muck mass accounting” and propose discriminating checks, corrective actions and prevention.","instruction":"混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Counting a mixed vehicle in both upper and lower records falsely reports overbreak and distorts ground interpretation. Conversely, assigning every unexplained difference to density may hide genuine profile excess and localized ground loss. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。","observationEn":"Link to the mechanism: Conversely, assigning every unexplained difference to density may hide genuine profile excess and localized ground loss.","failure":"誤判風險：若相信「出碴重量和幾何量不符時，只要修改密度就能解決。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-24-k1","title":"失效模式","titleEn":"Failure mode","text":"混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。","textEn":"Counting a mixed vehicle in both upper and lower records falsely reports overbreak and distorts ground interpretation. Conversely, assigning every unexplained difference to density may hide genuine profile excess and localized ground loss.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「開挖與出碴質量帳」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Excavation and muck mass accounting\" shows distress, which diagnosis is most reasonable?","options":["混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。","只要結構還沒倒，就代表安全餘裕仍然足夠。","只要每天施工仰拱，最終一定會追上仍前進的掌子面。"],"optionsEn":["Counting a mixed vehicle in both upper and lower records falsely reports overbreak and distorts ground interpretation.","As long as the structure is still standing, its safety margin must still be adequate.","Daily invert construction necessarily catches a face that continues advancing at any speed."],"answer":0,"explanation":"混裝車次被重複計入上下台階，會誤報超挖並影響地層判讀；反之把未知差額當成密度變化扣掉，可能掩蓋真實輪廓超出和局部掉落。 需以量測區分可能原因。","explanationEn":"Counting a mixed vehicle in both upper and lower records falsely reports overbreak and distorts ground interpretation. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b149-v14-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「閉合追趕與相對速度」與「測量閉合與基準誤差」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Closure catch-up and relative speed\" and \"Survey closure and reference uncertainty\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b149-v14-25","title":"閉合追趕與相對速度：機制與系統路徑","titleEn":"Closure catch-up and relative speed: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-24"],"objective":"說明「閉合追趕與相對速度」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Closure catch-up and relative speed” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"仰拱若落後上半面，其追趕時間由兩者相對速度決定，不能只用仰拱自身速度除以落後距離。持續推進的上半面同時增加待閉合長度，因此產能與支護時序必須放在同一條里程軸上。 假設初始落後20 m，上半前進2 m/day、仰拱完成3 m/day，縮短速度1 m/day，理想追平需20 days；若兩者皆2 m/day則距離不縮小。 仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「閉合追趕與相對速度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"If invert closure trails the upper face, catch-up depends on relative speed rather than closure speed alone. Continued upper advance adds open length at the same time. Production and support sequencing therefore need a shared chainage axis. Assume an initial 20 m gap, upper advance 2 m/day and invert completion 3 m/day. The gap shrinks at 1 m/day, requiring 20 days ideally; equal 2 m/day speeds never close it. When invert output matches upper advance, closure work occurs every shift but the gap never narrows. Treating cumulative completion as successful catch-up hides the persistent open length in production reporting. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Closure catch-up and relative speed” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「只要每天施工仰拱，最終一定會追上仍前進的掌子面。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Daily invert construction necessarily catches a face that continues advancing at any speed.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「閉合追趕與相對速度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Closure catch-up and relative speed”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-25-k1","title":"閉合追趕與相對速度","titleEn":"Closure catch-up and relative speed","text":"仰拱若落後上半面，其追趕時間由兩者相對速度決定，不能只用仰拱自身速度除以落後距離。持續推進的上半面同時增加待閉合長度，因此產能與支護時序必須放在同一條里程軸上。","textEn":"If invert closure trails the upper face, catch-up depends on relative speed rather than closure speed alone. Continued upper advance adds open length at the same time.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要每天施工仰拱，最終一定會追上仍前進的掌子面。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Daily invert construction necessarily catches a face that continues advancing at any speed. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「閉合追趕與相對速度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Closure catch-up and relative speed\" is correct?","options":["只要每天施工仰拱，最終一定會追上仍前進的掌子面。","仰拱若落後上半面，其追趕時間由兩者相對速度決定，不能只用仰拱自身速度除以落後距離。","多量幾次取平均就能消除任何種類的測量誤差。"],"optionsEn":["Daily invert construction necessarily catches a face that continues advancing at any speed.","If invert closure trails the upper face, catch-up depends on relative speed rather than closure speed alone.","Repeating measurements and averaging removes every type of measurement error, including systematic bias."],"answer":1,"explanation":"仰拱若落後上半面，其追趕時間由兩者相對速度決定，不能只用仰拱自身速度除以落後距離。 其餘選項是常見誤解。","explanationEn":"If invert closure trails the upper face, catch-up depends on relative speed rather than closure speed alone. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b149-v14-26","title":"閉合追趕與相對速度：定量估算","titleEn":"Closure catch-up and relative speed: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-25"],"objective":"以數值模型估算「閉合追趕與相對速度」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Closure catch-up and relative speed” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設初始落後20 m，上半前進2 m/day、仰拱完成3 m/day，縮短速度1 m/day，理想追平需20 days；若兩者皆2 m/day則距離不縮小。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume an initial 20 m gap, upper advance 2 m/day and invert completion 3 m/day. The gap shrinks at 1 m/day, requiring 20 days ideally; equal 2 m/day speeds never close it. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：每天量測上半與仰拱有效完成里程，仰拱須依傳力與品質條件認定完成而非只看外形；以兩條累計曲線之差檢查預測，停機和返工分別註記，不能用計畫速度代替實際可用進度。","observationEn":"How to cross-check: Measure upper-face and effectively completed invert chainage daily.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設初始落後20 m，上半前進2 m/day、仰拱完成3 m/day，縮短速度1 m/day，理想追平需20 days；若兩者皆2 m/day則距離不縮小。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume an initial 20 m gap, upper advance 2 m/day and invert completion 3 m/day. The gap shrinks at 1 m/day, requiring 20 days ideally; equal 2 m/day speeds never close it.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「閉合追趕與相對速度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Closure catch-up and relative speed\", which statement holds?","options":["平均斷面尺寸合格就表示所有淨空介面都合格。","台階長度維持固定就代表每個斷面的受力歷程相同。","教學假設，非現場設定或設計允收值。"],"optionsEn":["Acceptable average section dimensions guarantee that every clearance interface is acceptable.","A fixed bench length means that every section experiences an identical loading history.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b149-v14-27","title":"閉合追趕與相對速度：試驗與驗證","titleEn":"Closure catch-up and relative speed: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「閉合追趕與相對速度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Closure catch-up and relative speed” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"每天量測上半與仰拱有效完成里程，仰拱須依傳力與品質條件認定完成而非只看外形；以兩條累計曲線之差檢查預測，停機和返工分別註記，不能用計畫速度代替實際可用進度。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure upper-face and effectively completed invert chainage daily. Completion requires load-transfer and quality conditions, not shape alone. Check forecasts against the difference between cumulative curves, marking shutdown and rework separately rather than substituting planned speeds for actual progress. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：進度會議保留兩條里程曲線和相對速度，異常落後與品質返工另列；是否調整上半或仰拱節奏由設計與施工主管共同核准。","observationEn":"Site practice: Progress reviews retain both chainage curves and relative speed, listing abnormal lag and quality rework separately. Design and construction leads jointly authorize any change to upper-face or invert timing.","failure":"注意干擾：仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: When invert output matches upper advance, closure work occurs every shift but the gap never narrows. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-27-k1","title":"驗證方法","titleEn":"Verification method","text":"每天量測上半與仰拱有效完成里程，仰拱須依傳力與品質條件認定完成而非只看外形；以兩條累計曲線之差檢查預測，停機和返工分別註記，不能用計畫速度代替實際可用進度。","textEn":"Measure upper-face and effectively completed invert chainage daily. Completion requires load-transfer and quality conditions, not shape alone. Check forecasts against the difference between cumulative curves, marking shutdown and rework separately rather than substituting planned speeds for actual progress.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-27-k2","title":"現場實務","titleEn":"Site practice","text":"進度會議保留兩條里程曲線和相對速度，異常落後與品質返工另列；是否調整上半或仰拱節奏由設計與施工主管共同核准。","textEn":"Progress reviews retain both chainage curves and relative speed, listing abnormal lag and quality rework separately. Design and construction leads jointly authorize any change to upper-face or invert timing.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「閉合追趕與相對速度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Closure catch-up and relative speed\"?","options":["每天量測上半與仰拱有效完成里程，仰拱須依傳力與品質條件認定完成而非只看外形；以兩條累計曲線之差檢查預測，停機和返工分別註記，不能用計畫速度代替實際可用進度。","量測時不必記錄溫度、水頭、開挖序列與施工荷重，因為它們不會影響結果。","核心保留體積比例就是它提供的抗力比例。"],"optionsEn":["Measure upper-face and effectively completed invert chainage daily.","Temperature, water head, excavation sequence and construction loads need not be recorded because they cannot affect the result.","The retained core volume percentage equals the percentage of resistance it provides."],"answer":0,"explanation":"每天量測上半與仰拱有效完成里程，仰拱須依傳力與品質條件認定完成而非只看外形；以兩條累計曲線之差檢查預測，停機和返工分別註記，不能用計畫速度代替實際可用進度。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure upper-face and effectively completed invert chainage daily. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b149-v14-28","title":"閉合追趕與相對速度：失效診斷","titleEn":"Closure catch-up and relative speed: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-27"],"objective":"從症狀倒推「閉合追趕與相對速度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Closure catch-up and relative speed” and propose discriminating checks, corrective actions and prevention.","instruction":"仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"When invert output matches upper advance, closure work occurs every shift but the gap never narrows. Treating cumulative completion as successful catch-up hides the persistent open length in production reporting. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。","observationEn":"Link to the mechanism: Treating cumulative completion as successful catch-up hides the persistent open length in production reporting.","failure":"誤判風險：若相信「只要每天施工仰拱，最終一定會追上仍前進的掌子面。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Daily invert construction necessarily catches a face that continues advancing at any speed.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-28-k1","title":"失效模式","titleEn":"Failure mode","text":"仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。","textEn":"When invert output matches upper advance, closure work occurs every shift but the gap never narrows. Treating cumulative completion as successful catch-up hides the persistent open length in production reporting.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「閉合追趕與相對速度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Closure catch-up and relative speed\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。","多量幾次取平均就能消除任何種類的測量誤差。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","When invert output matches upper advance, closure work occurs every shift but the gap never narrows.","Repeating measurements and averaging removes every type of measurement error, including systematic bias."],"answer":1,"explanation":"仰拱產能等於上半進尺時，看似每班都有閉合工作但落後距離永不縮小；若把累計完成量當成追趕成效，暴露長度會在報表中被錯誤隱藏。 需以量測區分可能原因。","explanationEn":"When invert output matches upper advance, closure work occurs every shift but the gap never narrows. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b149-v14-29","title":"測量閉合與基準誤差：機制與系統路徑","titleEn":"Survey closure and reference uncertainty: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-28"],"objective":"說明「測量閉合與基準誤差」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Survey closure and reference uncertainty” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"拱頂沉陷與兩側收斂使用不同幾何投影，必須維持可追溯的基準和符號定義。重複測量可降低獨立隨機誤差，但共用基準位移會同時影響全部讀值，不能藉平均消除。 假設四次獨立讀值各標準差1 mm，平均標準差1/√4=0.5 mm；若另有共用基準偏差2 mm，它仍為2 mm，不隨四次平均消失。 基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「測量閉合與基準誤差」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Crown settlement and side convergence use different geometric projections and need traceable references and sign conventions. Repetition can reduce independent random uncertainty, while movement of a shared reference biases every observation and cannot be removed by averaging. Assume four independent readings each with standard deviation 1 mm. Their mean has 1/√4=0.5 mm standard deviation. A shared 2 mm reference bias remains 2 mm despite averaging. A reference slowly settling inside the construction influence zone makes every observation understate true movement while remaining repeatable. A small standard deviation alone can therefore confuse measurement precision with accuracy and conceal systematic error. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Survey closure and reference uncertainty” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「多量幾次取平均就能消除任何種類的測量誤差。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Repeating measurements and averaging removes every type of measurement error, including systematic bias.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「測量閉合與基準誤差」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Survey closure and reference uncertainty”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-29-k1","title":"測量閉合與基準誤差","titleEn":"Survey closure and reference uncertainty","text":"拱頂沉陷與兩側收斂使用不同幾何投影，必須維持可追溯的基準和符號定義。重複測量可降低獨立隨機誤差，但共用基準位移會同時影響全部讀值，不能藉平均消除。","textEn":"Crown settlement and side convergence use different geometric projections and need traceable references and sign conventions. Repetition can reduce independent random uncertainty, while movement of a shared reference biases every observation and cannot be removed by averaging.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：多量幾次取平均就能消除任何種類的測量誤差。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Repeating measurements and averaging removes every type of measurement error, including systematic bias. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「測量閉合與基準誤差」，下列哪一項敘述正確？","questionEn":"Which statement about \"Survey closure and reference uncertainty\" is correct?","options":["多量幾次取平均就能消除任何種類的測量誤差。","只要排水設備足夠大，增加湧水就不需要地工判讀。","拱頂沉陷與兩側收斂使用不同幾何投影，必須維持可追溯的基準和符號定義。"],"optionsEn":["Repeating measurements and averaging removes every type of measurement error, including systematic bias.","Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.","Crown settlement and side convergence use different geometric projections and need traceable references and sign conventions."],"answer":2,"explanation":"拱頂沉陷與兩側收斂使用不同幾何投影，必須維持可追溯的基準和符號定義。 其餘選項是常見誤解。","explanationEn":"Crown settlement and side convergence use different geometric projections and need traceable references and sign conventions. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b149-v14-30","title":"測量閉合與基準誤差：定量估算","titleEn":"Survey closure and reference uncertainty: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-29"],"objective":"以數值模型估算「測量閉合與基準誤差」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Survey closure and reference uncertainty” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設四次獨立讀值各標準差1 mm，平均標準差1/√4=0.5 mm；若另有共用基準偏差2 mm，它仍為2 mm，不隨四次平均消失。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume four independent readings each with standard deviation 1 mm. Their mean has 1/√4=0.5 mm standard deviation. A shared 2 mm reference bias remains 2 mm despite averaging. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以區外穩定控制點和閉合測量檢查基準，保存原始高程、儀器設站與時間；將獨立誤差和共同偏差分開列示，若多點同步跳變先查基準，再比較施工事件，不以刪除同日全部資料處理異常。","observationEn":"How to cross-check: Use stable external control and closure measurements to check references, retaining original elevations, setups and times.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設四次獨立讀值各標準差1 mm，平均標準差1/√4=0.5 mm；若另有共用基準偏差2 mm，它仍為2 mm，不隨四次平均消失。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume four independent readings each with standard deviation 1 mm. Their mean has 1/√4=0.5 mm standard deviation. A shared 2 mm reference bias remains 2 mm despite averaging.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「測量閉合與基準誤差」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Survey closure and reference uncertainty\", which statement holds?","options":["教學假設，非現場設定或設計允收值。","總荷載不變就表示左右拱腳需求一定不變。","名義拱腳寬度乘長度永遠等於有效接觸面積。"],"optionsEn":["Teaching assumptions, not operating settings or design acceptance limits.","An unchanged total load means that demand at each arch foot must also remain unchanged.","Nominal arch-foot width multiplied by length always equals the effective loaded contact area."],"answer":0,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b149-v14-31","title":"測量閉合與基準誤差：試驗與驗證","titleEn":"Survey closure and reference uncertainty: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「測量閉合與基準誤差」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Survey closure and reference uncertainty” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以區外穩定控制點和閉合測量檢查基準，保存原始高程、儀器設站與時間；將獨立誤差和共同偏差分開列示，若多點同步跳變先查基準，再比較施工事件，不以刪除同日全部資料處理異常。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use stable external control and closure measurements to check references, retaining original elevations, setups and times. Report independent uncertainty separately from common bias. If many points jump together, investigate the reference before comparing construction events; deleting the entire day is not a diagnosis. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：監測交接含基準穩定證據及修正版本，任何整體位移修正需測量主管簽認；設計者使用數據前確認共同偏差未被重複讀值的精密度掩蓋。","observationEn":"Site practice: Monitoring handover includes reference-stability evidence and correction versions. The survey lead approves any common-shift correction, and the designer confirms that repeated-reading precision has not concealed shared bias before using the data.","failure":"注意干擾：基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A reference slowly settling inside the construction influence zone makes every observation understate true movement while remaining repeatable. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-31-k1","title":"驗證方法","titleEn":"Verification method","text":"以區外穩定控制點和閉合測量檢查基準，保存原始高程、儀器設站與時間；將獨立誤差和共同偏差分開列示，若多點同步跳變先查基準，再比較施工事件，不以刪除同日全部資料處理異常。","textEn":"Use stable external control and closure measurements to check references, retaining original elevations, setups and times. Report independent uncertainty separately from common bias. If many points jump together, investigate the reference before comparing construction events; deleting the entire day is not a diagnosis.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-31-k2","title":"現場實務","titleEn":"Site practice","text":"監測交接含基準穩定證據及修正版本，任何整體位移修正需測量主管簽認；設計者使用數據前確認共同偏差未被重複讀值的精密度掩蓋。","textEn":"Monitoring handover includes reference-stability evidence and correction versions. The survey lead approves any common-shift correction, and the designer confirms that repeated-reading precision has not concealed shared bias before using the data.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「測量閉合與基準誤差」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Survey closure and reference uncertainty\"?","options":["沿用另一條隧道或另一處地層的量測結果，就可視為本工程已完成驗證。","以區外穩定控制點和閉合測量檢查基準，保存原始高程、儀器設站與時間。","左右沉陷平均不大就能排除偏轉與接縫問題。"],"optionsEn":["Reusing results from another tunnel or ground formation counts as verifying this structure.","Use stable external control and closure measurements to check references, retaining original elevations, setups and times.","A small average of left and right settlements rules out rotation and joint problems."],"answer":1,"explanation":"以區外穩定控制點和閉合測量檢查基準，保存原始高程、儀器設站與時間；將獨立誤差和共同偏差分開列示，若多點同步跳變先查基準，再比較施工事件，不以刪除同日全部資料處理異常。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use stable external control and closure measurements to check references, retaining original elevations, setups and times. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b149-v14-32","title":"測量閉合與基準誤差：失效診斷","titleEn":"Survey closure and reference uncertainty: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-31"],"objective":"從症狀倒推「測量閉合與基準誤差」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Survey closure and reference uncertainty” and propose discriminating checks, corrective actions and prevention.","instruction":"基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A reference slowly settling inside the construction influence zone makes every observation understate true movement while remaining repeatable. A small standard deviation alone can therefore confuse measurement precision with accuracy and conceal systematic error. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。","observationEn":"Link to the mechanism: A small standard deviation alone can therefore confuse measurement precision with accuracy and conceal systematic error.","failure":"誤判風險：若相信「多量幾次取平均就能消除任何種類的測量誤差。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Repeating measurements and averaging removes every type of measurement error, including systematic bias.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-32-k1","title":"失效模式","titleEn":"Failure mode","text":"基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。","textEn":"A reference slowly settling inside the construction influence zone makes every observation understate true movement while remaining repeatable. A small standard deviation alone can therefore confuse measurement precision with accuracy and conceal systematic error.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「測量閉合與基準誤差」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Survey closure and reference uncertainty\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","只要排水設備足夠大，增加湧水就不需要地工判讀。","基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.","A reference slowly settling inside the construction influence zone makes every observation understate true movement while remaining repeatable."],"answer":2,"explanation":"基準點在施工影響區內緩慢下沉，所有量測會低估真實沉陷而仍保持良好重複性；僅以標準差很小判定資料可靠，會錯把精密度當成正確度。 需以量測區分可能原因。","explanationEn":"A reference slowly settling inside the construction influence zone makes every observation understate true movement while remaining repeatable. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b149-v14-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「台階排水與滲流邊界」與「閉合後淨空與驗收餘量」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Bench drainage and seepage boundaries\" and \"Post-closure clearance and acceptance allowance\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b149-v14-33","title":"台階排水與滲流邊界：機制與系統路徑","titleEn":"Bench drainage and seepage boundaries: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-32"],"objective":"說明「台階排水與滲流邊界」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Bench drainage and seepage boundaries” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"下半開挖可能改變排水出口與水頭差，流量變化不一定等於滲透係數改變。Darcy一維模型要求飽和層流與明確流徑，實際節理集中流及開挖三維效應必須另行辨識。 假設k=0.0001 m/s、A=15 m²、Δh=8 m、L=12 m，Q=kAΔh/L=0.001 m³/s=3.6 m³/h；水頭差減半則Q減半。 排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「台階排水與滲流邊界」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Lower excavation can change drainage outlets and head differences, so altered flow need not mean altered conductivity. A one-dimensional Darcy model requires saturated laminar flow and a defined path; fracture concentration and three-dimensional excavation effects require separate interpretation. Assume k=0.0001 m/s, A=15 m², Δh=8 m and L=12 m. Q=kAΔh/L=0.001 m³/s=3.6 m³/h; halving head difference halves this ideal flow. Lowering an outlet can increase hydraulic gradient and fine-particle loss. Flow may rise before visible movement appears. Focusing only on pump capacity can therefore overlook an erosion mechanism affecting the ground and support beneath the bench. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Bench drainage and seepage boundaries” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「只要排水設備足夠大，增加湧水就不需要地工判讀。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「台階排水與滲流邊界」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Bench drainage and seepage boundaries”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-33-k1","title":"台階排水與滲流邊界","titleEn":"Bench drainage and seepage boundaries","text":"下半開挖可能改變排水出口與水頭差，流量變化不一定等於滲透係數改變。Darcy一維模型要求飽和層流與明確流徑，實際節理集中流及開挖三維效應必須另行辨識。","textEn":"Lower excavation can change drainage outlets and head differences, so altered flow need not mean altered conductivity. A one-dimensional Darcy model requires saturated laminar flow and a defined path; fracture concentration and three-dimensional excavation effects require separate interpretation.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要排水設備足夠大，增加湧水就不需要地工判讀。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「台階排水與滲流邊界」，下列哪一項敘述正確？","questionEn":"Which statement about \"Bench drainage and seepage boundaries\" is correct?","options":["下半開挖可能改變排水出口與水頭差，流量變化不一定等於滲透係數改變。","只要排水設備足夠大，增加湧水就不需要地工判讀。","平均斷面尺寸合格就表示所有淨空介面都合格。"],"optionsEn":["Lower excavation can change drainage outlets and head differences, so altered flow need not mean altered conductivity.","Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.","Acceptable average section dimensions guarantee that every clearance interface is acceptable."],"answer":0,"explanation":"下半開挖可能改變排水出口與水頭差，流量變化不一定等於滲透係數改變。 其餘選項是常見誤解。","explanationEn":"Lower excavation can change drainage outlets and head differences, so altered flow need not mean altered conductivity. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b149-v14-34","title":"台階排水與滲流邊界：定量估算","titleEn":"Bench drainage and seepage boundaries: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-33"],"objective":"以數值模型估算「台階排水與滲流邊界」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Bench drainage and seepage boundaries” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設k=0.0001 m/s、A=15 m²、Δh=8 m、L=12 m，Q=kAΔh/L=0.001 m³/s=3.6 m³/h；水頭差減半則Q減半。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume k=0.0001 m/s, A=15 m², Δh=8 m and L=12 m. Q=kAΔh/L=0.001 m³/s=3.6 m³/h; halving head difference halves this ideal flow. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將量水、孔壓和出口高程同步記錄，確認開挖後水頭基準是否改變；比較流量與濁度的時間關係，集中裂隙流不能硬塞進均勻介質公式，異常須由水文地工人員檢查流徑與地層損失。","observationEn":"How to cross-check: Record discharge, pore pressure and outlet elevation together, checking whether excavation changed the head reference.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設k=0.0001 m/s、A=15 m²、Δh=8 m、L=12 m，Q=kAΔh/L=0.001 m³/s=3.6 m³/h；水頭差減半則Q減半。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume k=0.0001 m/s, A=15 m², Δh=8 m and L=12 m. Q=kAΔh/L=0.001 m³/s=3.6 m³/h; halving head difference halves this ideal flow.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「台階排水與滲流邊界」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Bench drainage and seepage boundaries\", which statement holds?","options":["台階長度維持固定就代表每個斷面的受力歷程相同。","教學假設，非現場設定或設計允收值。","核心保留體積比例就是它提供的抗力比例。"],"optionsEn":["A fixed bench length means that every section experiences an identical loading history.","Teaching assumptions, not operating settings or design acceptance limits.","The retained core volume percentage equals the percentage of resistance it provides."],"answer":1,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b149-v14-35","title":"台階排水與滲流邊界：試驗與驗證","titleEn":"Bench drainage and seepage boundaries: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「台階排水與滲流邊界」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Bench drainage and seepage boundaries” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將量水、孔壓和出口高程同步記錄，確認開挖後水頭基準是否改變；比較流量與濁度的時間關係，集中裂隙流不能硬塞進均勻介質公式，異常須由水文地工人員檢查流徑與地層損失。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record discharge, pore pressure and outlet elevation together, checking whether excavation changed the head reference. Compare flow and turbidity histories. Concentrated fracture flow cannot be forced into a homogeneous-medium formula; hydrogeotechnical specialists review anomalous pathways and possible ground loss. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：交接排水路徑、孔壓趨勢和濁度異常，不只交泵浦運轉時數；任何改變水頭邊界的方案由水文與支護設計者核准，課堂流量不作抽排設定。","observationEn":"Site practice: Hand over drainage paths, pressure trends and turbidity anomalies rather than pump hours alone. Hydraulic and support designers approve changes to head boundaries; the classroom discharge is not a pumping setting.","failure":"注意干擾：排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Lowering an outlet can increase hydraulic gradient and fine-particle loss. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-35-k1","title":"驗證方法","titleEn":"Verification method","text":"將量水、孔壓和出口高程同步記錄，確認開挖後水頭基準是否改變；比較流量與濁度的時間關係，集中裂隙流不能硬塞進均勻介質公式，異常須由水文地工人員檢查流徑與地層損失。","textEn":"Record discharge, pore pressure and outlet elevation together, checking whether excavation changed the head reference. Compare flow and turbidity histories. Concentrated fracture flow cannot be forced into a homogeneous-medium formula; hydrogeotechnical specialists review anomalous pathways and possible ground loss.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-35-k2","title":"現場實務","titleEn":"Site practice","text":"交接排水路徑、孔壓趨勢和濁度異常，不只交泵浦運轉時數；任何改變水頭邊界的方案由水文與支護設計者核准，課堂流量不作抽排設定。","textEn":"Hand over drainage paths, pressure trends and turbidity anomalies rather than pump hours alone. Hydraulic and support designers approve changes to head boundaries; the classroom discharge is not a pumping setting.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「台階排水與滲流邊界」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Bench drainage and seepage boundaries\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","出碴重量和幾何量不符時，只要修改密度就能解決。","將量水、孔壓和出口高程同步記錄，確認開挖後水頭基準是否改變；比較流量與濁度的時間關係，集中裂隙流不能硬塞進均勻介質公式，異常須由水文地工人員檢查流徑與地層損失。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Whenever muck mass and geometry disagree, changing the assumed density resolves the problem.","Record discharge, pore pressure and outlet elevation together, checking whether excavation changed the head reference."],"answer":2,"explanation":"將量水、孔壓和出口高程同步記錄，確認開挖後水頭基準是否改變；比較流量與濁度的時間關係，集中裂隙流不能硬塞進均勻介質公式，異常須由水文地工人員檢查流徑與地層損失。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record discharge, pore pressure and outlet elevation together, checking whether excavation changed the head reference. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b149-v14-36","title":"台階排水與滲流邊界：失效診斷","titleEn":"Bench drainage and seepage boundaries: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-35"],"objective":"從症狀倒推「台階排水與滲流邊界」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Bench drainage and seepage boundaries” and propose discriminating checks, corrective actions and prevention.","instruction":"排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Lowering an outlet can increase hydraulic gradient and fine-particle loss. Flow may rise before visible movement appears. Focusing only on pump capacity can therefore overlook an erosion mechanism affecting the ground and support beneath the bench. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。","observationEn":"Link to the mechanism: Focusing only on pump capacity can therefore overlook an erosion mechanism affecting the ground and support beneath the bench.","failure":"誤判風險：若相信「只要排水設備足夠大，增加湧水就不需要地工判讀。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Sufficient pumping capacity makes additional inflow irrelevant to geotechnical interpretation and support review.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-36-k1","title":"失效模式","titleEn":"Failure mode","text":"排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。","textEn":"Lowering an outlet can increase hydraulic gradient and fine-particle loss. Flow may rise before visible movement appears. Focusing only on pump capacity can therefore overlook an erosion mechanism affecting the ground and support beneath the bench.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「台階排水與滲流邊界」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Bench drainage and seepage boundaries\" shows distress, which diagnosis is most reasonable?","options":["排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","平均斷面尺寸合格就表示所有淨空介面都合格。"],"optionsEn":["Lowering an outlet can increase hydraulic gradient and fine-particle loss.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Acceptable average section dimensions guarantee that every clearance interface is acceptable."],"answer":0,"explanation":"排水出口下移可能增加水力梯度和細料流失，流量上升卻未必出現立即明顯變形；若只看抽排設備能否負荷，地層侵蝕的機制就可能被忽略。 需以量測區分可能原因。","explanationEn":"Lowering an outlet can increase hydraulic gradient and fine-particle loss. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b149-v14-37","title":"閉合後淨空與驗收餘量：機制與系統路徑","titleEn":"Post-closure clearance and acceptance allowance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-36"],"objective":"說明「閉合後淨空與驗收餘量」如何影響隧道台階法施工的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Post-closure clearance and acceptance allowance” governs forces, deformation, flow or signals in “Bench excavation for tunnels”, and map the relevant inputs, transfer paths and boundaries.","instruction":"襯砌變形、厚度與量測不確定度共同影響可交付淨空，名義設計線不等於竣工可用界面。淨空餘量計算必須使用同一坐標與方向，並保留未來允許變形和設備安裝需求的獨立項目。 假設實測高度5.20 m、所需高度5.05 m、保守量測扣減0.03 m，剩餘餘量5.20-5.05-0.03=0.12 m；未含未來變形預留。 局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「閉合後淨空與驗收餘量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Deformation, lining thickness and measurement uncertainty jointly determine deliverable clearance. A nominal design line is not the as-built usable interface. Allowance calculations require common coordinates and directions, with future permitted movement and installation needs listed separately. Assume measured height 5.20 m, required height 5.05 m and conservative measurement deduction 0.03 m. Remaining allowance is 0.12 m, before reserving future movement. Local thickening or brackets can intrude into clearance despite acceptable average dimensions. Checking only centerline height before handover leaves sidewall and corner conflicts to emerge later during equipment installation or maintenance planning. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Post-closure clearance and acceptance allowance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非現場設定或設計允收值。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not operating settings or design acceptance limits.","failure":"常見誤解：「平均斷面尺寸合格就表示所有淨空介面都合格。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Acceptable average section dimensions guarantee that every clearance interface is acceptable.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「閉合後淨空與驗收餘量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Post-closure clearance and acceptance allowance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b149-v14-37-k1","title":"閉合後淨空與驗收餘量","titleEn":"Post-closure clearance and acceptance allowance","text":"襯砌變形、厚度與量測不確定度共同影響可交付淨空，名義設計線不等於竣工可用界面。淨空餘量計算必須使用同一坐標與方向，並保留未來允許變形和設備安裝需求的獨立項目。","textEn":"Deformation, lining thickness and measurement uncertainty jointly determine deliverable clearance. A nominal design line is not the as-built usable interface.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：平均斷面尺寸合格就表示所有淨空介面都合格。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Acceptable average section dimensions guarantee that every clearance interface is acceptable. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"關於「閉合後淨空與驗收餘量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Post-closure clearance and acceptance allowance\" is correct?","options":["平均斷面尺寸合格就表示所有淨空介面都合格。","襯砌變形、厚度與量測不確定度共同影響可交付淨空，名義設計線不等於竣工可用界面。","總荷載不變就表示左右拱腳需求一定不變。"],"optionsEn":["Acceptable average section dimensions guarantee that every clearance interface is acceptable.","Deformation, lining thickness and measurement uncertainty jointly determine deliverable clearance.","An unchanged total load means that demand at each arch foot must also remain unchanged."],"answer":1,"explanation":"襯砌變形、厚度與量測不確定度共同影響可交付淨空，名義設計線不等於竣工可用界面。 其餘選項是常見誤解。","explanationEn":"Deformation, lining thickness and measurement uncertainty jointly determine deliverable clearance. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b149-v14-38","title":"閉合後淨空與驗收餘量：定量估算","titleEn":"Post-closure clearance and acceptance allowance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-37"],"objective":"以數值模型估算「閉合後淨空與驗收餘量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Post-closure clearance and acceptance allowance” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非現場設定或設計允收值。假設實測高度5.20 m、所需高度5.05 m、保守量測扣減0.03 m，剩餘餘量5.20-5.05-0.03=0.12 m；未含未來變形預留。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not operating settings or design acceptance limits. Assume measured height 5.20 m, required height 5.05 m and conservative measurement deduction 0.03 m. Remaining allowance is 0.12 m, before reserving future movement. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用同一坐標系的全斷面掃描檢查最小距離，確認局部凸出、排水和設備支架皆納入；將量測扣減與設計變形預留分開，剩餘餘量不足時送界面設計審查，不能以斷面平均高度代替最不利點。","observationEn":"How to cross-check: Check minimum distances using full-section scans in a common coordinate system, including local protrusions, drainage and equipment brackets.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b149-v14-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非現場設定或設計允收值。假設實測高度5.20 m、所需高度5.05 m、保守量測扣減0.03 m，剩餘餘量5.20-5.05-0.03=0.12 m；未含未來變形預留。","textEn":"Teaching assumptions, not operating settings or design acceptance limits. Assume measured height 5.20 m, required height 5.05 m and conservative measurement deduction 0.03 m. Remaining allowance is 0.12 m, before reserving future movement.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"依「閉合後淨空與驗收餘量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Post-closure clearance and acceptance allowance\", which statement holds?","options":["名義拱腳寬度乘長度永遠等於有效接觸面積。","左右沉陷平均不大就能排除偏轉與接縫問題。","教學假設，非現場設定或設計允收值。"],"optionsEn":["Nominal arch-foot width multiplied by length always equals the effective loaded contact area.","A small average of left and right settlements rules out rotation and joint problems.","Teaching assumptions, not operating settings or design acceptance limits."],"answer":2,"explanation":"教學假設，非現場設定或設計允收值。 重算時請保留單位。","explanationEn":"Teaching assumptions, not operating settings or design acceptance limits. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b149-v14-39","title":"閉合後淨空與驗收餘量：試驗與驗證","titleEn":"Post-closure clearance and acceptance allowance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「閉合後淨空與驗收餘量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Post-closure clearance and acceptance allowance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用同一坐標系的全斷面掃描檢查最小距離，確認局部凸出、排水和設備支架皆納入；將量測扣減與設計變形預留分開，剩餘餘量不足時送界面設計審查，不能以斷面平均高度代替最不利點。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check minimum distances using full-section scans in a common coordinate system, including local protrusions, drainage and equipment brackets. Separate measurement deductions from design movement reserves. Inadequate remaining allowance needs interface review; mean section height cannot replace the adverse point. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將最不利點、坐標基準和扣減項目一併交接，保存掃描原檔；土建、設備及維護代表共同確認淨空責任界面後完成驗收。","observationEn":"Site practice: Hand over adverse locations, coordinate references and deductions together with original scans. Civil, equipment and maintenance representatives jointly confirm responsibility for clearance interfaces before acceptance is completed.","failure":"注意干擾：局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Local thickening or brackets can intrude into clearance despite acceptable average dimensions. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b149-v14-39-k1","title":"驗證方法","titleEn":"Verification method","text":"用同一坐標系的全斷面掃描檢查最小距離，確認局部凸出、排水和設備支架皆納入；將量測扣減與設計變形預留分開，剩餘餘量不足時送界面設計審查，不能以斷面平均高度代替最不利點。","textEn":"Check minimum distances using full-section scans in a common coordinate system, including local protrusions, drainage and equipment brackets. Separate measurement deductions from design movement reserves. Inadequate remaining allowance needs interface review; mean section height cannot replace the adverse point.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-39-k2","title":"現場實務","titleEn":"Site practice","text":"將最不利點、坐標基準和扣減項目一併交接，保存掃描原檔；土建、設備及維護代表共同確認淨空責任界面後完成驗收。","textEn":"Hand over adverse locations, coordinate references and deductions together with original scans. Civil, equipment and maintenance representatives jointly confirm responsibility for clearance interfaces before acceptance is completed.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"要驗證「閉合後淨空與驗收餘量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Post-closure clearance and acceptance allowance\"?","options":["用同一坐標系的全斷面掃描檢查最小距離，確認局部凸出、排水和設備支架皆納入。","不確定度太難估計，報告中只寫最佳值即可。","只要每天施工仰拱，最終一定會追上仍前進的掌子面。"],"optionsEn":["Check minimum distances using full-section scans in a common coordinate system, including local protrusions, drainage and equipment brackets.","Uncertainty is too hard to estimate, so the report may state only the best value.","Daily invert construction necessarily catches a face that continues advancing at any speed."],"answer":0,"explanation":"用同一坐標系的全斷面掃描檢查最小距離，確認局部凸出、排水和設備支架皆納入；將量測扣減與設計變形預留分開，剩餘餘量不足時送界面設計審查，不能以斷面平均高度代替最不利點。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check minimum distances using full-section scans in a common coordinate system, including local protrusions, drainage and equipment brackets. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b149-v14-40","title":"閉合後淨空與驗收餘量：失效診斷","titleEn":"Post-closure clearance and acceptance allowance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"prerequisiteIds":["b149-v14-39"],"objective":"從症狀倒推「閉合後淨空與驗收餘量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Post-closure clearance and acceptance allowance” and propose discriminating checks, corrective actions and prevention.","instruction":"局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Local thickening or brackets can intrude into clearance despite acceptable average dimensions. Checking only centerline height before handover leaves sidewall and corner conflicts to emerge later during equipment installation or maintenance planning. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。","observationEn":"Link to the mechanism: Checking only centerline height before handover leaves sidewall and corner conflicts to emerge later during equipment installation or maintenance planning.","failure":"誤判風險：若相信「平均斷面尺寸合格就表示所有淨空介面都合格。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Acceptable average section dimensions guarantee that every clearance interface is acceptable.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b149-v14-40-k1","title":"失效模式","titleEn":"Failure mode","text":"局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。","textEn":"Local thickening or brackets can intrude into clearance despite acceptable average dimensions. Checking only centerline height before handover leaves sidewall and corner conflicts to emerge later during equipment installation or maintenance planning.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]},{"id":"b149-v14-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"]}],"quiz":{"question":"在「閉合後淨空與驗收餘量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Post-closure clearance and acceptance allowance\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。","總荷載不變就表示左右拱腳需求一定不變。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Local thickening or brackets can intrude into clearance despite acceptable average dimensions.","An unchanged total load means that demand at each arch foot must also remain unchanged."],"answer":1,"explanation":"局部噴層增厚或支架突出會侵入淨空，即使平均斷面符合也可能影響設備安裝；若交接前只檢查中心線高度，側牆與角隅的介面衝突可能延後才被發現。 需以量測區分可能原因。","explanationEn":"Local thickening or brackets can intrude into clearance despite acceptable average dimensions. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v14s-crossrail-scl","v14s-crossrail-stepney","v14s-fhwa"],"curriculumVersion":14,"stepCount":40,"estimatedMinutes":1000}};
